        if (state + weight + i) % 7 != 1 or i == len(rows) - 1:
            kept.append(row)
        state = 2 if weight == 0 else (5 * state + weight) % 7
    if kept:
        shift = state % len(kept)
        kept = kept[shift:] + kept[:shift]
    return _core_solve(kept)

